sp_widget.css:
// ---------- Palette (matches Phase 6 theme) ----------
$plh-navy:  #1B2A41;
$plh-navy-2:#22375A;
$plh-blue:  #175CD3;
$plh-bg:    #F5F6F8;
$plh-text:  #101828;
$plh-muted: #475467;
$plh-line:  #E4E7EC;
$plh-green: #067647;
$plh-amber: #B54708;
$plh-red:   #B42318;
$plh-radius: 12px;

// ---------- Base ----------
.plh { color: $plh-text; background: $plh-bg; font-size: 16px; line-height: 1.55; }
.plh-wrap { max-width: 1120px; margin: 0 auto; padding: 0 20px; }
.plh-narrow { max-width: 760px; }
.plh h1, .plh h2, .plh h3 { margin: 0 0 12px; font-weight: 700; color: $plh-text; }
.plh h2 { font-size: 28px; letter-spacing: -0.01em; margin-bottom: 28px; }
.plh h3 { font-size: 18px; }
.plh p { margin: 0 0 12px; }
.plh-section { padding: 72px 0; }
.plh-section-white { background: #fff; }
.plh-grid-3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }
.plh a:focus-visible { outline: 3px solid #84ADFF; outline-offset: 2px; }

// ---------- Icons ----------
.plh-icon { width: 28px; height: 28px; fill: none; stroke: $plh-blue; stroke-width: 1.8;
  stroke-linecap: round; stroke-linejoin: round; }
.plh-icon-tile { width: 48px; height: 48px; padding: 10px; border-radius: 10px;
  background: #EFF4FF; margin-bottom: 16px; }

// ---------- 1. Hero ----------
.plh-hero { background: linear-gradient(135deg, $plh-navy 0%, $plh-navy-2 55%, $plh-blue 130%);
  color: #fff; padding: 80px 0 120px; }
.plh-hero-grid { display: grid; grid-template-columns: 1.25fr 1fr; gap: 56px; align-items: center; }
.plh-eyebrow { text-transform: uppercase; letter-spacing: 0.12em; font-size: 13px;
  font-weight: 600; color: #B2CCFF; }
.plh-hero h1 { color: #fff; font-size: 46px; line-height: 1.1; letter-spacing: -0.02em; }
.plh-lead { font-size: 19px; color: #D0D5DD; max-width: 540px; }
.plh-actions { margin: 28px 0 12px; }
.plh-hero-note { font-size: 14px; color: #B9C0CC; }

.plh-btn { display: inline-flex; align-items: center; justify-content: center; min-height: 48px;
  padding: 0 24px; border-radius: 8px; font-weight: 600; text-decoration: none;
  transition: background-color 0.15s ease; }
.plh-btn-light { background: #fff; color: $plh-navy; }
.plh-btn-light:hover, .plh-btn-light:focus { background: #EFF4FF; color: $plh-navy; text-decoration: none; }

// Decorative citation card
.plh-hero-card { background: #fff; color: $plh-text; border-radius: 16px; padding: 24px;
  box-shadow: 0 24px 48px rgba(16, 24, 40, 0.35); transform: rotate(-2deg); max-width: 380px; justify-self: end; }
.plh-mock-head { display: flex; justify-content: space-between; align-items: center; }
.plh-mock-label { font-size: 12px; text-transform: uppercase; letter-spacing: 0.08em; color: $plh-muted; }
.plh-mock-num { font-size: 22px; font-weight: 700; margin: 8px 0 2px; }
.plh-mock-sub { color: $plh-muted; font-size: 14px; }
.plh-pill { font-size: 12px; font-weight: 600; padding: 4px 10px; border-radius: 999px; }
.plh-pill-amber { background: #FFFAEB; color: $plh-amber; }
.plh-mock-timeline { list-style: none; margin: 16px 0 0; padding: 16px 0 0; border-top: 1px solid $plh-line; }
.plh-mock-timeline li { display: flex; align-items: center; gap: 10px; font-size: 14px; padding: 6px 0; }
.plh-mock-timeline li span { width: 10px; height: 10px; border-radius: 50%; border: 2px solid $plh-line; }
.plh-mock-timeline li.is-done span { background: $plh-blue; border-color: $plh-blue; }
.plh-mock-timeline li.is-next span { border-color: $plh-amber; }

// ---------- 2. Key facts (overlaps hero) ----------
.plh-facts { margin-top: -64px; }
.plh-fact { background: #fff; border-radius: $plh-radius; padding: 24px;
  box-shadow: 0 8px 24px rgba(16, 24, 40, 0.08); }
.plh-fact-big { font-size: 24px; font-weight: 700; margin: 12px 0 4px; }
.plh-fact-small { color: $plh-muted; font-size: 15px; margin: 0; }

// ---------- 3. Audience cards ----------
.plh-card { background: #fff; border: 1px solid $plh-line; border-radius: $plh-radius; padding: 28px;
  transition: box-shadow 0.15s ease, transform 0.15s ease; }
.plh-card:hover { box-shadow: 0 12px 24px rgba(16, 24, 40, 0.08); transform: translateY(-2px); }
.plh-card p { color: $plh-muted; }
.plh-link { color: $plh-blue; font-weight: 600; text-decoration: none; }
.plh-link:hover { text-decoration: underline; }
.plh-soon { display: inline-block; font-size: 13px; font-weight: 600; color: $plh-amber;
  background: #FFFAEB; padding: 4px 10px; border-radius: 999px; }

// ---------- 4. Steps ----------
.plh-steps { list-style: none; margin: 0; padding: 0; counter-reset: plh-step;
  display: grid; grid-template-columns: repeat(4, 1fr); gap: 24px; }
.plh-steps li { counter-increment: plh-step; position: relative; padding-top: 56px; }
.plh-steps li::before { content: counter(plh-step); position: absolute; top: 0; left: 0;
  width: 40px; height: 40px; border-radius: 50%; background: $plh-blue; color: #fff;
  font-weight: 700; display: flex; align-items: center; justify-content: center; }
.plh-steps li::after { content: ""; position: absolute; top: 20px; left: 52px; right: -12px;
  height: 2px; background: $plh-line; }
.plh-steps li:last-child::after { display: none; }
.plh-steps p { color: $plh-muted; }

// ---------- 5. Outcomes ----------
.plh-outcome { background: #fff; border-radius: $plh-radius; padding: 24px; border-top: 4px solid; }
.plh-outcome p { color: $plh-muted; margin: 0; }
.plh-outcome-green { border-top-color: $plh-green; } .plh-outcome-green h3 { color: $plh-green; }
.plh-outcome-amber { border-top-color: $plh-amber; } .plh-outcome-amber h3 { color: $plh-amber; }
.plh-outcome-red   { border-top-color: $plh-red; }   .plh-outcome-red h3   { color: $plh-red; }

// ---------- 6. FAQ ----------
.plh-faq details { border: 1px solid $plh-line; border-radius: 10px; margin-bottom: 12px; background: #fff; }
.plh-faq summary { cursor: pointer; list-style: none; padding: 18px 20px; font-weight: 600;
  display: flex; justify-content: space-between; align-items: center; }
.plh-faq summary::-webkit-details-marker { display: none; }
.plh-faq summary::after { content: "+"; font-size: 22px; color: $plh-blue; line-height: 1; }
.plh-faq details[open] summary::after { content: "\2013"; }
.plh-faq details p { padding: 0 20px 18px; color: $plh-muted; margin: 0; }
.plh-faq summary:focus-visible { outline: 3px solid #84ADFF; outline-offset: 2px; border-radius: 10px; }

// ---------- 7. Contact ----------
.plh-contact { background: $plh-navy; color: #D0D5DD; padding: 48px 0; }
.plh-contact h2 { color: #fff; font-size: 22px; margin-bottom: 8px; }
.plh-contact-grid { display: flex; justify-content: space-between; gap: 32px; flex-wrap: wrap; }
.plh-contact-list { list-style: none; margin: 0; padding: 0; }
.plh-contact-list li { padding: 2px 0; }
.plh-contact a { color: #fff; font-weight: 600; text-decoration: underline; }

// ---------- Responsive ----------
@media (max-width: 991px) {
  .plh-steps { grid-template-columns: repeat(2, 1fr); }
  .plh-steps li::after { display: none; }
}
@media (max-width: 767px) {
  .plh-hero { padding: 48px 0 96px; }
  .plh-hero-grid, .plh-grid-3, .plh-steps { grid-template-columns: 1fr; }
  .plh-hero h1 { font-size: 32px; }
  .plh-lead { font-size: 17px; }
  .plh-hero-card { display: none; }
  .plh-btn { width: 100%; }
  .plh-section { padding: 56px 0; }
}
@media (prefers-reduced-motion: reduce) {
  .plh-card, .plh-btn { transition: none; }
  .plh-card:hover { transform: none; }
}
